/**
 * Portrait panel for the OG cards, base64-inlined.
 *
 * The cards run on the edge runtime, so there is no fs, and fetching it
 * from the site at build time would be circular.
 *
 * It is pre-cropped to exactly the 400x630 column it renders into
 * (public/og/bijal-ogpanel-400x630.jpg, cut from the 1080 master). The
 * 400px author crop was square, so the card would have upscaled it 1.6x
 * and shown it soft; the 1080 master would have put 270KB of base64 into
 * every edge function. This is 54KB and pixel-exact.
 */

export const portrait =
  'data:image/jpeg;base64,';
